// Ensures the shared status table exists before every write — cheap
// no-op if it already does. Same idempotent CREATE TABLE IF NOT EXISTS
// discipline as godaddy/sql/upgrade_from_3.0.0.sql, just run inline
// rather than as a separate manual step (Ward, Aug 2026 — "a node red
// task that initializes it, and keeps it up to date"). Identical in
// every flow that writes status — duplicated on purpose, matching this
// project's existing preference for self-contained nodes over a shared-
// context module pattern.
msg.topic = "CREATE TABLE IF NOT EXISTS job_status (" +
    "job_name TEXT PRIMARY KEY, last_success TEXT, last_attempt TEXT, " +
    "last_attempt_ok INTEGER, last_error TEXT, checkpoint TEXT, updated_at TEXT)";
return msg;

// Builds the UPSERT from msg.sqlite_job (set by job_success/job_failed
// above). 'success' mode updates last_success and clears last_error;
// 'failure' mode updates last_error and deliberately leaves last_success
// untouched (a failure shouldn't erase the last known-good run). checkpoint
// is job-specific optional state (only oura_sync uses it, for its self-heal
// fetch window) — only touched when the caller actually supplies one.
function esc(s) { return "'" + String(s).replace(/'/g, "''") + "'"; }
function sqlVal(v) { return (v === null || v === undefined) ? 'NULL' : (typeof v === 'number' ? v : esc(v)); }
const j = msg.sqlite_job;
const now = new Date().toISOString();
const cols = ['job_name', 'last_success', 'last_attempt', 'last_attempt_ok', 'last_error', 'checkpoint', 'updated_at'];
const vals = [j.job_name, j.last_success ?? null, j.last_attempt, j.last_attempt_ok, j.last_error ?? null, j.checkpoint ?? null, now];
const setClauses = ['last_attempt=excluded.last_attempt', 'last_attempt_ok=excluded.last_attempt_ok', 'updated_at=excluded.updated_at'];
if (j.mode === 'success') {
    setClauses.push('last_success=excluded.last_success', 'last_error=NULL');
    if (j.checkpoint !== undefined && j.checkpoint !== null) setClauses.push('checkpoint=excluded.checkpoint');
} else {
    setClauses.push('last_error=excluded.last_error');
}
msg.topic = 'INSERT INTO job_status (' + cols.join(', ') + ') VALUES (' + vals.map(sqlVal).join(', ') + ') ' +
    'ON CONFLICT(job_name) DO UPDATE SET ' + setClauses.join(', ');
return msg;

// Shared annotated-CSV parser (adapted from wherewhen_data_restore_flow.json's
// parseFluxCsvToLines — same header-detection/multi-block logic, different
// output shape: plain row objects instead of line-protocol strings, since
// the analysis engine needs to compute with the data, not just rewrite it).
// Same known limitation carried over: naive comma-split, not RFC4180-quote-
// aware — fine given none of this project's actual field values contain a
// literal comma today (same reasoning as the restore flow's own note).
function parseFluxCsvToRows(csvText) {
    const RESERVED = new Set(['result', 'table', '_start', '_stop', '_time', '_value', '_field', '_measurement']);
    const rawLines = (csvText || '').split('\n').map(l => l.replace(/\r$/, ''));
    let header = null;
    const rows = [];

    function arraysEqual(a, b) { return a.length === b.length && a.every((v, i) => v === b[i]); }

    rawLines.forEach(raw => {
        if (raw === '') return; // blank separator between table blocks — next real row re-detects header
        if (raw.startsWith('#')) return; // #datatype/#group/#default — not needed here
        const cols = raw.split(',');
        // A header row is identified by carrying ALL THREE reserved
        // column-name markers as literal cell values (_measurement,
        // _field, _value) — not just one, and NOT "differs from the
        // previous header" (that was the original, buggy heuristic: two
        // consecutive table blocks with the same tag SET but different
        // tag VALUES produce identical header rows, which the old
        // !arraysEqual() check wrongly let fall through as a data row).
        // Real data will essentially never carry all three of those
        // exact strings as its own field/measurement/tag values.
        if (cols.includes('_measurement') && cols.includes('_field') && cols.includes('_value')) {
            header = cols;
            return;
        }
        if (!header) return; // stray row before any header seen
        if (cols.length !== header.length) return; // malformed/short row

        const row = {};
        header.forEach((colName, i) => { row[colName] = cols[i]; });

        const measurement = row['_measurement'];
        const field = row['_field'];
        const value = row['_value'];
        const time = row['_time'];
        if (!measurement || !field || value === undefined || value === '' || !time) return;

        const tags = {};
        header.forEach(colName => {
            if (!RESERVED.has(colName) && colName !== '' && row[colName] !== undefined && row[colName] !== '') {
                tags[colName] = row[colName];
            }
        });

        rows.push({ measurement, field, value, time, tags });
    });

    return rows;
}

// Fulgrim Flux Analysis Engine — analysis definitions (PLAN.md §11).
// Drafted standalone first so the JS can be brace/syntax-checked with
// Node before being embedded into Node-RED flow JSON as an escaped string.
//
// DESIGN CALL (Aug 2026, since PLAN.md left "exact Flux queries" open):
// Flux's own job here is deliberately kept to from|range|filter|pivot|sort
// — the same primitives already proven working elsewhere in this repo
// (wherewhen_data_export/restore's queries). All statistics (correlation
// coefficients, clustering counts, trend direction) are computed in plain
// JS in Node-RED after the CSV comes back, not inside Flux itself — Flux
// has covariance/stats packages that COULD do some of this, but their
// exact behavior/availability on Ward's actual InfluxDB install has never
// been confirmed, whereas a hand-written Pearson correlation in JS is
// something I can get right with high confidence without live testing.
// Matches PLAN.md's own framing: "Node-RED orchestrates... shapes results."
//
// TIER COVERAGE (Aug 2026 call, also left open by PLAN.md): rather than
// hand-assign which of the 20 analyses run at which of the 4 tiers
// (daily/weekly/monthly/all), EVERY analysis runs at EVERY tier that
// fires, just over that tier's own window/refresh cadence. Simpler, one
// code path, and "wrong" only in the sense of some extra recompute work
// on data that hasn't changed — cheap given this project's actual data
// volume (one person's health log, not fleet-scale).

// ---------- shared stats helpers ----------

function mean(arr) { return arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : null; }

function pearsonCorrelation(xs, ys) {
    // xs/ys must already be the same length, same index = same day/point,
    // nulls already filtered out by the caller (alignByDay below).
    const n = xs.length;
    if (n < 3) return null; // not enough points for a meaningful coefficient
    const mx = mean(xs), my = mean(ys);
    let num = 0, dx2 = 0, dy2 = 0;
    for (let i = 0; i < n; i++) {
        const dx = xs[i] - mx, dy = ys[i] - my;
        num += dx * dy; dx2 += dx * dx; dy2 += dy * dy;
    }
    if (dx2 === 0 || dy2 === 0) return null; // no variance in one series — correlation undefined, not zero
    return num / Math.sqrt(dx2 * dy2);
}

// Simple linear trend: least-squares slope of value vs. day-index.
// Returns null if fewer than 3 points. Positive = rising, negative = falling.
function linearTrendSlope(points) { // points: [{t: dayIndexNumber, v: number}]
    const n = points.length;
    if (n < 3) return null;
    const mt = mean(points.map(p => p.t)), mv = mean(points.map(p => p.v));
    let num = 0, den = 0;
    points.forEach(p => { num += (p.t - mt) * (p.v - mv); den += (p.t - mt) * (p.t - mt); });
    return den === 0 ? null : num / den;
}

// Rows from parseFluxCsvToRows (shared parser, see analysis_engine_flow.json's
// own copy of the header-detection logic already proven in wherewhen_data_restore_flow.json)
// come back as: [{measurement, field, value, time, tags: {...}}]. Most
// analyses want one specific field per row (already field-filtered by the
// Flux query itself, via pivot() or a field filter), reduced to one
// value-per-day. dayKeyFn extracts the grouping key (usually the ISO date
// portion of `time`, but can be overridden e.g. for tag-keyed data).
// Eastern-local calendar-date key for a raw UTC timestamp -- day-
            // grouping (toDaySeries()'s default, and every direct
            // r.time-based day bucket below: incidents, medication
            // events, therapy sessions, night-waking notes) needs ONE
            // authoritative "which day" answer picked at compute time,
            // unlike clock-time DISPLAY (analysis_render.php/analysis.php
            // now do that client-side, per the viewer's own browser --
            // see the comment on bedtime_wake_time_trend's shape() for
            // why that one is different). Grouping can't be deferred to
            // display time the same way without re-deriving every trend
            // series from raw points on every page load, so this picks a
            // fixed real-world zone instead -- America/New_York, since
            // this is Ward's own single-user data. Previous behavior
            // (easternDateKey(r.time), a UTC calendar-date slice) put
            // anything after roughly 7-8pm Eastern on the NEXT UTC day --
            // e.g. a 10:35pm bedtime (2:35am UTC) was counted as
            // belonging to the following day, not the night it was
            // actually part of. Uses Intl (DST-safe) rather than a fixed
            // UTC-4/-5 offset, which would silently be wrong half the
            // year.
            // Ward, Aug 2026: "let the user set their preferred timezone" instead
            // of hardcoding one -- see settings.php / api/get_shared_config.php.
            // flow.get() rather than msg.preferred_timezone for the same
            // reason msg.secrets/period_type already go through flow context
            // in this flow (n_ae_build_flux_query/n_ae_parse_and_shape run
            // post-split, one message per analysis -- flow context is this
            // flow's established way of getting values to every one of those
            // without relying on msg surviving the split/http-request nodes
            // in between). Undefined (a fresh install that hasn't fetched
            // shared config yet, or the test flow below, which never
            // populates this) and an invalid saved zone both fall back the
            // same way get_shared_config.php's own server-side default does.
            const PREFERRED_TZ = (typeof flow !== 'undefined' && flow.get('ae_preferred_timezone')) || 'America/New_York';
            let EASTERN_DATE_FMT;
            try {
                EASTERN_DATE_FMT = new Intl.DateTimeFormat('en-CA', { timeZone: PREFERRED_TZ, year: 'numeric', month: '2-digit', day: '2-digit' });
            } catch (e) {
                node.warn('Invalid preferred_timezone "' + PREFERRED_TZ + '" -- falling back to America/New_York. ' + e.message);
                EASTERN_DATE_FMT = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/New_York', year: 'numeric', month: '2-digit', day: '2-digit' });
            }
            function easternDateKey(isoUtc) {
                return EASTERN_DATE_FMT.format(new Date(isoUtc));
            }
            // Real bug, Aug 2026 (Ward's own real data): three long_sleep-
            // typed sessions with bedtime timestamps in the early
            // afternoon/early evening (2:46pm, 5:07pm, 5:36pm in the
            // user's preferred timezone) turned up as a night's "main
            // session" in #1-4 and #19, each with sharply lower
            // efficiency than every genuine night (36%, 52%, 65%, vs.
            // Ward's normal 70-87% range) and, for two of the three, an
            // oddly exact 15h00m00s time_in_bed -- almost certainly an
            // extended low-movement period (e.g. sitting still at a
            // desk) that Oura's own algorithm eventually classified as
            // long_sleep once it ran past whatever duration threshold
            // stops treating it as a rejectable nap ("rest" type) --
            // exactly the ring-misreads-stillness scenario Ward
            // described. Genuine sleep onset essentially never happens
            // between noon and 6pm, so a long_sleep candidate whose
            // bedtime falls in that window is treated as not a real
            // night and excluded, the same way a physically-impossible
            // field value already was. Deliberately narrow (noon-6pm,
            // not e.g. noon-8pm) -- a handful of real 7-8pm bedtimes are
            // in Ward's actual data and are plausible, not artifacts.
            let BEDTIME_HOUR_FMT;
            try {
                BEDTIME_HOUR_FMT = new Intl.DateTimeFormat('en-US', { timeZone: PREFERRED_TZ, hour: 'numeric', hour12: false });
            } catch (e) {
                BEDTIME_HOUR_FMT = new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', hour: 'numeric', hour12: false });
            }
            function isImplausibleBedtimeHour(isoUtc) {
                const hour = Number(BEDTIME_HOUR_FMT.format(new Date(isoUtc))) % 24;
                return hour >= 12 && hour < 18;
            }
            function toDaySeries(rows, dayKeyFn) {
    dayKeyFn = dayKeyFn || (r => easternDateKey(r.time));
    const byDay = {};
    rows.forEach(r => {
        const day = dayKeyFn(r);
        const v = Number(r.value);
        if (!Number.isFinite(v)) return;
        // Keep the LAST value seen per day per field (matches this
        // project's existing "latest wins" convention, e.g. body comp
        // import's collapse-to-latest-per-day rule).
        byDay[day] = v;
    });
    return Object.entries(byDay).sort((a, b) => a[0] < b[0] ? -1 : 1).map(([date, value]) => ({ date, value }));
}

// Groups Oura-sleep field rows by Eastern night (bedtime's own Eastern
// calendar date) and keeps only the value from that night's LONGEST
// session (by time_in_bed) -- same principle as #19/#20's own night-
// selection fixes. Real bug, Aug 2026, confirmed against Ward's actual
// exported data for both #1 (sleep_duration_trend: 14 of 46 days were
// sub-1-hour fragment values) and #19: naps/fragments were silently
// overwriting real nights via toDaySeries()'s plain "last value wins"
// collapse (Flux sorts by _time, so a same-day nap occurring AFTER the
// real night's own _time would win). rows: pre-filtered to the ONE
// target field. timeInBedRows: time_in_bed rows from the same query
// window (fetched alongside), used only to pick each night's longest
// session -- not charted itself. min/max: still enforced per-candidate
// (a physically-impossible value is never a candidate, regardless of
// its session's length) -- same bounds-guard reasoning as the
// boundedTrendResult() this replaces, just combined with night-
// selection instead of applied on its own.
function mainSessionTrendResult(rows, timeInBedRows, min, max, label) {
    const durByTime = {};
    timeInBedRows.forEach(r => { durByTime[r.time] = Number(r.value); });
    const byNight = {};
    const excluded = [];
    rows.forEach(r => {
        const v = Number(r.value);
        if (!Number.isFinite(v) || v < min || v > max) {
            excluded.push({ time: r.time, value: r.value });
            return;
        }
        if (isImplausibleBedtimeHour(r.time)) {
            excluded.push({ time: r.time, value: r.value });
            return;
        }
        const key = easternDateKey(r.time);
        const dur = durByTime[r.time] ?? 0;
        if (!byNight[key] || dur > byNight[key].dur) byNight[key] = { date: key, value: v, dur };
    });
    const series = Object.values(byNight).sort((a, b) => a.date < b.date ? -1 : 1).map(({ date, value }) => ({ date, value }));
    const result = trendResult(series, label);
    if (excluded.length) {
        result.excluded_count = excluded.length;
        result.excluded_sample = excluded.slice(0, 5);
    }
    return result;
}

// Aligns two day-series to only the days present in BOTH — required
// before any correlation, since Pearson needs paired points.
function alignByDay(seriesA, seriesB) {
    const bByDay = {}; seriesB.forEach(p => { bByDay[p.date] = p.value; });
    const xs = [], ys = [], dates = [];
    seriesA.forEach(p => {
        if (bByDay[p.date] !== undefined) { xs.push(p.value); ys.push(bByDay[p.date]); dates.push(p.date); }
    });
    return { xs, ys, dates };
}

function trendResult(series, label) {
    const points = series.map((p, i) => ({ t: i, v: p.value }));
    return {
        series, // [{date, value}]
        count: series.length,
        average: mean(series.map(p => p.value)),
        latest: series.length ? series[series.length - 1] : null,
        trend_slope_per_day: linearTrendSlope(points),
        label,
    };
}

function correlationResult(seriesA, seriesB, labelA, labelB) {
    const { xs, ys, dates } = alignByDay(seriesA, seriesB);
    return {
        label: labelA + ' vs ' + labelB,
        paired_days: dates.length,
        correlation: pearsonCorrelation(xs, ys),
        points: dates.map((d, i) => ({ date: d, [labelA]: xs[i], [labelB]: ys[i] })),
    };
}

// ---------- Flux query builders ----------
// All take (bucket, startISO, stopISO) and return a Flux query string.
// A null/empty stopISO means "through now" (Flux's range() stop defaults
// to now() when omitted).

function fluxFieldTrend(bucket, start, stop, measurement, field, extraFilter) {
    const stopClause = stop ? ', stop: ' + stop : '';
    const filter = extraFilter ? ' and ' + extraFilter : '';
    return 'from(bucket: "' + bucket + '")\n' +
        '  |> range(start: ' + start + stopClause + ')\n' +
        '  |> filter(fn: (r) => r._measurement == "' + measurement + '" and r._field == "' + field + '"' + filter + ')\n' +
        '  |> sort(columns: ["_time"])';
}

