            // matches PLAN.md #16's own framing ("capture why he woke,"
            // not a number to trend).
            const entries = rows.filter(r => r.field === 'night_waking_notes' && r.value).map(r => ({ date: easternDateKey(r.time), note: r.value }));
            return { label: 'Night-waking context', entries, count: entries.length };
        },
    },

    // ---- Headline / cross-cutting (#17-20) ----

    full_correlation_matrix: {
        n: 17,
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => (r._measurement == "incidents") or (r._measurement == "daily_log_manual" and (r._field == "alcohol_drinks" or r._field == "caffeine_servings" or r._field == "weight" or r._field == "mood_rating")) or (r._measurement == "oura_sleep" and (r._field == "efficiency" or r._field == "average_hrv") and (r.type == "long_sleep" or r.type == "sleep")) or (r._measurement == "daily_log_manual" and r._field == "exercise_minutes"))\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            const incidentDays = {};
            rows.filter(r => r.measurement === 'incidents').forEach(r => { const d = easternDateKey(r.time); incidentDays[d] = (incidentDays[d] || 0) + 1; });
            const series = {
                incidents: Object.entries(incidentDays).sort().map(([date, value]) => ({ date, value })),
                alcohol: toDaySeries(rows.filter(r => r.field === 'alcohol_drinks')),
                caffeine: toDaySeries(rows.filter(r => r.field === 'caffeine_servings')),
                weight: toDaySeries(rows.filter(r => r.field === 'weight')),
                mood: toDaySeries(rows.filter(r => r.field === 'mood_rating')),
                sleep_efficiency: toDaySeries(rows.filter(r => r.field === 'efficiency')),
                hrv: toDaySeries(rows.filter(r => r.field === 'average_hrv')),
                exercise_minutes: toDaySeries(rows.filter(r => r.field === 'exercise_minutes')),
            };
            const keys = Object.keys(series);
            const matrix = [];
            keys.forEach(a => keys.forEach(b2 => {
                if (a >= b2) return; // upper triangle only, avoid duplicate/self pairs
                const { xs, ys } = alignByDay(series[a], series[b2]);
                matrix.push({ a, b: b2, correlation: pearsonCorrelation(xs, ys), paired_days: xs.length });
            }));
            return { label: 'Full correlation matrix', factors: keys, matrix, note: 'Small-dataset correlations — treat as exploratory, not statistically confirmed, until data volume grows (Ward said as much when this analysis was planned, PLAN.md section 11).' };
        },
    },
    unreported_anxiety_detection: {
        n: 18,
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => r._measurement == "incidents" or (r._measurement == "oura_sleep" and (r._field == "average_hrv" or r._field == "lowest_heart_rate" or r._field == "efficiency") and (r.type == "long_sleep" or r.type == "sleep")))\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            const incidentDays = new Set(rows.filter(r => r.measurement === 'incidents').map(r => easternDateKey(r.time)));
            const hrv = toDaySeries(rows.filter(r => r.field === 'average_hrv'));
            const rhr = toDaySeries(rows.filter(r => r.field === 'lowest_heart_rate'));
            const eff = toDaySeries(rows.filter(r => r.field === 'efficiency'));
            function baseline(series, onIncidentDays) {
                const vals = series.filter(p => onIncidentDays === incidentDays.has(p.date)).map(p => p.value);
                return { avg: mean(vals), n: vals.length };
            }
            const hrvIncident = baseline(hrv, true), hrvNormal = baseline(hrv, false);
            const rhrIncident = baseline(rhr, true), rhrNormal = baseline(rhr, false);
            const effIncident = baseline(eff, true), effNormal = baseline(eff, false);
            // Flag a NON-incident day as a possible unreported-anxiety day
            // if HRV is below the incident-day average AND resting HR is
            // above the incident-day average AND sleep efficiency is
            // below the incident-day average — all three, deliberately
            // conservative (fewer false positives) since this is a
            // pattern-match against a small baseline, not a diagnosis.
            const flagged = [];
            hrv.forEach(p => {
                if (incidentDays.has(p.date)) return;
                const r = rhr.find(x => x.date === p.date);
                const e = eff.find(x => x.date === p.date);
                if (!r || !e || hrvIncident.avg === null || rhrIncident.avg === null || effIncident.avg === null) return;
                if (p.value <= hrvIncident.avg && r.value >= rhrIncident.avg && e.value <= effIncident.avg) {
                    flagged.push({ date: p.date, hrv: p.value, resting_hr: r.value, sleep_efficiency: e.value });
                }
            });
            return {
                label: 'Unreported-anxiety detection',
                incident_day_baseline: { hrv: hrvIncident, resting_hr: rhrIncident, sleep_efficiency: effIncident },
                normal_day_baseline: { hrv: hrvNormal, resting_hr: rhrNormal, sleep_efficiency: effNormal },
                flagged_days: flagged,
                note: 'Pattern-match against known incident days, not a diagnosis — needs real incident history to mean anything, per PLAN.md section 11 analysis #18. Likely to want more data before trusting.',
            };
        },
    },
    bedtime_wake_time_trend: {
        n: 19,
        // Needs BOTH time_in_bed (fallback) and bedtime_end (Oura's own
        // real "got out of bed" timestamp, captured starting Aug 2026) --
        // a plain single-field fluxFieldTrend() query isn't enough here.
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => r._measurement == "oura_sleep" and (r._field == "time_in_bed" or r._field == "bedtime_end") and r.type == "long_sleep")\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            // bedtime_start IS the row's own _time (see oura_sync_flow.json's
            // sleepRecordToLine). Wake time prefers Oura's own bedtime_end
            // field when present; falls back to bedtime + time_in_bed for
            // any record synced before bedtime_end was captured. PLAN.md
            // #19's own flagged uncertainty about the time_in_bed
            // derivation turned out to be a real problem, confirmed
            // against Ward's real data (Aug 2026): even after fixing the
            // display timezone AND grouping to one session per night,
            // bedtime + time_in_bed still gave 9-14 HOUR "nights" -- far
            // more than Ward's own reported ~5-6 hours. time_in_bed
            // evidently includes time lying awake in bed after actually
            // waking, not just time asleep -- bedtime_end is Oura's own
            // answer to exactly that, so it wins whenever available.
            const byTime = {};
            rows.forEach(r => {
                byTime[r.time] = byTime[r.time] || {};
                if (r.field === 'time_in_bed') byTime[r.time].time_in_bed = Number(r.value);
                if (r.field === 'bedtime_end') byTime[r.time].bedtime_end = r.value;
            });
            const rawPoints = Object.entries(byTime).map(([t, f]) => {
                const bedtime = new Date(t);
                let wake;
                if (f.bedtime_end) {
                    wake = new Date(f.bedtime_end);
                } else if (Number.isFinite(f.time_in_bed)) {
                    wake = new Date(bedtime.getTime() + f.time_in_bed * 1000);
                } else {
                    return null; // neither field present -- don't fabricate a point
                }
                return { bedtime_time: bedtime.toISOString(), wake_time: wake.toISOString() };
            }).filter(Boolean);

            // Real bug, Aug 2026 (Ward's own real data): naps and
            // fragmented sessions (ring removed/reattached mid-sleep)
            // were being averaged in right alongside real nights -- a
            // ~1-hour fragment counts exactly as much as an ~11-hour real
            // night in a plain average, which is how "average bedtime
            // 8:40pm, average wake 2:53am" happened even though the
            // underlying UTC-to-Eastern conversion was already correct.
            // Same principle as #20's hypnogram night-selection fix:
            // group by the Eastern calendar date of BEDTIME (one logical
            // "night"), keep only the LONGEST session in each group.
            // easternDateKey() (this file's own PREFERRED_TZ-driven
            // helper) supersedes this node's own separate hardcoded
            // America/New_York formatter that used to live here -- was
            // harmless while preferred_timezone defaulted to
            // America/New_York, but a real latent inconsistency once
            // someone sets a different preference.
            const excludedBedtime = [];
            const usablePoints = rawPoints.filter(p => {
                if (isImplausibleBedtimeHour(p.bedtime_time)) {
                    excludedBedtime.push({ time: p.bedtime_time, value: null });
                    return false;
                }
                return true;
            });
            const byNight = {};
            usablePoints.forEach(p => {
                const key = easternDateKey(p.bedtime_time);
                const dur = new Date(p.wake_time).getTime() - new Date(p.bedtime_time).getTime();
                if (!byNight[key] || dur > byNight[key].dur) byNight[key] = { ...p, dur };
            });
            const points = Object.values(byNight).map(({ dur, ...p }) => p);

            const result = {
                label: 'Bedtime / wake-time trend',
                series: points,
                note: 'bedtime_time/wake_time are raw UTC ISO timestamps; analysis_render.php converts to Eastern time for display and for grouping points into nights. wake_time uses bedtime_end when Oura provides it, otherwise falls back to bedtime + time_in_bed (runs noticeably long -- includes time lying awake in bed, not just asleep). Only the longest session per Eastern calendar night is kept, so naps/fragmented sessions do not skew the average. Sessions with an implausible noon-6pm bedtime are excluded outright -- almost always an extended still period misclassified as long_sleep, not a real night.',
            };
            if (excludedBedtime.length) {
                result.excluded_count = excludedBedtime.length;
                result.excluded_sample = excludedBedtime.slice(0, 5);
            }
            return result;
        },
    },
    sleep_stage_hypnogram: {
        n: 20,
        // Only the LONGEST night in the window is used (see shape()
        // below — picking by duration, not by which one started most
        // recently, matters here specifically) — a hypnogram is a per-
        // night chart, not a multi-night aggregate. Deliberately still
        // queries the SAME window as every
        // other analysis this run rather than a special narrower range —
        // one uniform period-window per run keeps the engine's one code
        // path simple; fetching more decomposed points than strictly
        // needed and discarding all but the latest night is wasteful but
        // cheap at this project's actual data volume.
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => r._measurement == "oura_sleep_stage")\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            // oura_sleep_stage only ever has one field ('value', see
            // decomposeSleepPhase() in oura_sync_flow.json) so this
            // filter is belt-and-suspenders rather than load-bearing —
            // consistent with the explicit field filters elsewhere in
            // this file, not strictly required by this measurement's own
            // shape the way it is for e.g. sleep_duration_trend.
            const stageRows = rows.filter(r => r.field === 'value');
            if (!stageRows.length) return { label: 'Sleep-stage timeline (hypnogram)', buckets: [], note: 'No decomposed oura_sleep_stage points in range yet.' };
            // Pick the LONGEST session (most buckets), not the one that
            // merely STARTED most recently (Ward, Aug 2026 — the old
            // "latest start time" pick was grabbing a short nap over the
            // actual previous night's sleep whenever a nap happened to
            // start later in the day than the real night began: "I go to
            // sleep one day and wake up the next," so day/start-time
            // isn't a reliable way to identify "the main night" at all —
            // duration is. A real night's sleep will always have far more
            // 15-minute buckets than a nap, so this is a robust proxy
            // without needing to cross-reference oura_sleep's own `type`
            // tag (long_sleep vs nap), which isn't carried onto these
            // decomposed oura_sleep_stage points in the first place.
            const bySleepId = {};
            stageRows.forEach(r => { (bySleepId[(r.tags && r.tags.sleep_id) || 'unknown'] = bySleepId[(r.tags && r.tags.sleep_id) || 'unknown'] || []).push(r); });
            const longestId = Object.keys(bySleepId).sort((a, b) => bySleepId[a].length - bySleepId[b].length).pop();
            const nightRows = bySleepId[longestId].sort((a, b) => a.time < b.time ? -1 : 1);
            const buckets = nightRows.map(r => ({ time: r.time, stage: (r.tags && r.tags.stage) || 'unknown' }));
            return {
                label: 'Sleep-stage timeline (hypnogram)',
                sleep_id: longestId,
                bounds: { start: buckets.length ? buckets[0].time : null, end: buckets.length ? buckets[buckets.length - 1].time : null },
                buckets,
                note: 'SLEEP_STAGE_MAP (1=deep/2=light/3=rem/4=awake) is assumed, not confirmed against real data — see the note in oura_sync_flow.json, PLAN.md section 11 analysis #20.',
            };
        },
    },
};

// ---- driver: exercises the CSV parser + all 20 shape() functions against
// embedded synthetic fixtures. Same idea as medical_history_import_test.json
// and wherewhen_data_restore_test.json — nothing on the target HA instance
// needs to exist for this to run, everything is self-contained.
const problems = [];

// ---- 1. CSV parser regression test — the exact bug found and fixed this
// session (header-detection false-negative on a repeated identical header
// row across two consecutive table blocks). ----
(function testCsvParser() {
    const csv = [
        '#datatype,string,long,dateTime:RFC3339,dateTime:RFC3339,dateTime:RFC3339,double,string,string,string,string',
        '#group,false,false,true,true,false,false,true,true,true,true',
        '#default,_result,,,,,,,,',
        ',result,table,_start,_stop,_time,_value,_field,_measurement,type,day',
        ',,0,2026-01-01T00:00:00Z,2027-01-01T00:00:00Z,2026-06-01T23:30:00Z,25200,total_sleep_duration,oura_sleep,long_sleep,2026-06-01',
        ',,0,2026-01-01T00:00:00Z,2027-01-01T00:00:00Z,2026-06-02T23:30:00Z,25300,total_sleep_duration,oura_sleep,long_sleep,2026-06-02',
        '',
        '#datatype,string,long,dateTime:RFC3339,dateTime:RFC3339,dateTime:RFC3339,double,string,string,string,string',
        '#group,false,false,true,true,false,false,true,true,true,true',
        '#default,_result,,,,,,,,',
        ',result,table,_start,_stop,_time,_value,_field,_measurement,type,day',
        ',,1,2026-01-01T00:00:00Z,2027-01-01T00:00:00Z,2026-06-01T23:30:00Z,82,efficiency,oura_sleep,long_sleep,2026-06-01',
        '',
    ].join('\n');
    const rows = parseFluxCsvToRows(csv);
    if (rows.length !== 3) {
        problems.push('CSV parser: expected 3 rows from a two-identical-header-block fixture, got ' + rows.length + ' — this is exactly the bug fixed this session (repeated header row misparsed as data). Rows: ' + JSON.stringify(rows));
    }
    const garbage = rows.find(r => r.measurement === '_measurement' || r.field === '_field');
    if (garbage) {
        problems.push('CSV parser: a header row leaked through as a data row: ' + JSON.stringify(garbage));
    }
})();

// ---- 2. Synthetic multi-measurement rows, same shape parseFluxCsvToRows produces ----
function mkRows() {
    const rows = [];
    const days = ['2026-06-01', '2026-06-02', '2026-06-03', '2026-06-04', '2026-06-05', '2026-06-06', '2026-06-07', '2026-06-08'];
    days.forEach((d, i) => {
        rows.push({ measurement: 'oura_sleep', field: 'total_sleep_duration', value: String(25200 + i * 100), time: d + 'T23:30:00Z', tags: { type: 'long_sleep', day: d } });
        rows.push({ measurement: 'oura_sleep', field: 'efficiency', value: String(80 + i), time: d + 'T23:30:00Z', tags: { type: 'long_sleep', day: d } });
        rows.push({ measurement: 'oura_sleep', field: 'average_hrv', value: String(40 + i), time: d + 'T23:30:00Z', tags: { type: 'long_sleep', day: d } });
        rows.push({ measurement: 'oura_sleep', field: 'lowest_heart_rate', value: String(55 - (i % 3)), time: d + 'T23:30:00Z', tags: { type: 'long_sleep', day: d } });
        rows.push({ measurement: 'oura_sleep', field: 'time_in_bed', value: String(27000 + i * 50), time: d + 'T23:30:00Z', tags: { type: 'long_sleep', day: d } });
        rows.push({ measurement: 'body_composition', field: 'weight_lb', value: String(200 - i * 0.2), time: d + 'T12:00:00Z', tags: { device_mac: 'aa', device_name: 'scale' } });
        rows.push({ measurement: 'daily_log_manual', field: 'weight', value: String(200 - i * 0.2), time: d + 'T12:00:00Z', tags: { log_date: d } });
        rows.push({ measurement: 'daily_log_manual', field: 'steps', value: String(4000 + i * 500), time: d + 'T12:00:00Z', tags: { log_date: d } });
        rows.push({ measurement: 'daily_log_manual', field: 'exercise_minutes', value: String(20 + i), time: d + 'T12:00:00Z', tags: { log_date: d } });
        rows.push({ measurement: 'daily_log_manual', field: 'standing_minutes', value: String(100 + i), time: d + 'T12:00:00Z', tags: { log_date: d } });
        rows.push({ measurement: 'daily_log_manual', field: 'alcohol_drinks', value: String(i % 3), time: d + 'T12:00:00Z', tags: { log_date: d } });
        rows.push({ measurement: 'daily_log_manual', field: 'caffeine_servings', value: String(1 + (i % 2)), time: d + 'T12:00:00Z', tags: { log_date: d } });
        rows.push({ measurement: 'daily_log_manual', field: 'mood_rating', value: String(5 + (i % 4)), time: d + 'T12:00:00Z', tags: { log_date: d } });
        rows.push({ measurement: 'daily_log_manual', field: 'state_of_mind', value: String(1 + (i % 5)), time: d + 'T12:00:00Z', tags: { log_date: d } });
        rows.push({ measurement: 'daily_log_manual', field: 'medications_all_taken', value: String(i % 2), time: d + 'T12:00:00Z', tags: { log_date: d } });
        rows.push({ measurement: 'daily_log_manual', field: 'night_waking_notes', value: i % 3 === 0 ? 'Woke around 2am, mind racing about work' : '', time: d + 'T12:00:00Z', tags: { log_date: d } });
    });
    ['2026-06-02T14:00:00Z', '2026-06-05T21:30:00Z'].forEach((t, idx) => {
        rows.push({ measurement: 'incidents', field: 'anxiety_intensity', value: String(6 + idx), time: t, tags: { category: idx === 0 ? 'anxiety' : 'cardiac' } });
        rows.push({ measurement: 'incidents', field: 'duration_minutes', value: String(30 + idx * 10), time: t, tags: { category: idx === 0 ? 'anxiety' : 'cardiac' } });
        rows.push({ measurement: 'incidents', field: 'chest_sensation', value: idx === 0 ? 'mild' : 'moderate', time: t, tags: { category: idx === 0 ? 'anxiety' : 'cardiac' } });
        rows.push({ measurement: 'incidents', field: 'shaking', value: 'mild', time: t, tags: { category: idx === 0 ? 'anxiety' : 'cardiac' } });
    });
    rows.push({ measurement: 'medications', field: 'frequency_days', value: '14', time: '2026-06-03T12:00:00Z', tags: { name: 'Evolocumab (Repatha)', med_type: 'scheduled' } });
    rows.push({ measurement: 'medications', field: 'frequency_days', value: '1', time: '2026-06-01T12:00:00Z', tags: { name: 'Aspirin', med_type: 'scheduled' } });
    rows.push({ measurement: 'medication_dosage_history', field: 'new_dosage', value: '20mg', time: '2026-06-04T12:00:00Z', tags: { medication_name: 'Duloxetine' } });
    rows.push({ measurement: 'therapy_sessions', field: 'mood_before', value: '4', time: '2026-06-03T17:00:00Z', tags: { session_type: 'individual' } });
    rows.push({ measurement: 'therapy_sessions', field: 'mood_after', value: '7', time: '2026-06-03T17:00:00Z', tags: { session_type: 'individual' } });
    for (let i = 0; i < 8; i++) {
        rows.push({ measurement: 'oura_sleep_stage', field: 'value', value: '1', time: new Date(new Date('2026-06-08T23:30:00Z').getTime() + i * 900000).toISOString(), tags: { sleep_id: 'abc123', stage: ['light', 'deep', 'rem', 'awake'][i % 4] } });
    }
    return rows;
}

// ---- 3. Run every shape() function, check it doesn't throw and returns
// JSON-serializable output — same as this session's own dev-time test,
// kept here so it re-runs on Ward's real instance too, not just once here. ----
const rows = mkRows();
const keys = Object.keys(ANALYSES);
if (keys.length !== 20) {
    problems.push('Expected exactly 20 analyses in the registry, found ' + keys.length + ': ' + keys.join(', '));
}
keys.forEach(key => {
    const def = ANALYSES[key];
    if (typeof def.flux !== 'function' || typeof def.shape !== 'function') {
        problems.push(key + ': missing flux() or shape() function');
        return;
    }
    try {
        const q = def.flux('testbucket', '2026-01-01T00:00:00Z', null);
        if (typeof q !== 'string' || !q.includes('from(bucket')) problems.push(key + ': flux() did not return a real Flux query string');
    } catch (e) {
        problems.push(key + ': flux() threw — ' + e.message);
    }
    try {
        const result = def.shape(rows);
        JSON.stringify(result); // must be push-able as JSON
        if (result === undefined || result === null) problems.push(key + ': shape() returned nothing');
    } catch (e) {
        problems.push(key + ': shape() threw — ' + e.message);
    }
});

// ---- 4. A few known-value spot checks, not just "didn't throw" ----
const sdt = ANALYSES.sleep_duration_trend.shape(rows);
if (!sdt.series || sdt.series.length !== 8) problems.push('sleep_duration_trend: expected 8 days of series data, got ' + (sdt.series ? sdt.series.length : 'none'));
if (sdt.trend_slope_per_day === null || sdt.trend_slope_per_day <= 0) problems.push('sleep_duration_trend: fixture data rises every day, expected a positive trend_slope_per_day, got ' + sdt.trend_slope_per_day);

const scc = ANALYSES.symptom_category_clustering.shape(rows);
if (scc.total_incidents !== 2) problems.push('symptom_category_clustering: expected 2 incidents from the fixture, got ' + scc.total_incidents);
if ((scc.by_category.anxiety || 0) !== 1 || (scc.by_category.cardiac || 0) !== 1) problems.push('symptom_category_clustering: expected 1 anxiety + 1 cardiac, got ' + JSON.stringify(scc.by_category));

const mac = ANALYSES.medication_adherence_vs_incidents.shape(rows);
if (mac.missed_dose_days === undefined || mac.full_adherence_days === undefined) problems.push('medication_adherence_vs_incidents: missing expected fields — ' + JSON.stringify(mac));

msg.payload = {
    result: problems.length ? 'PROBLEMS FOUND' : 'ALL CHECKS PASSED',
    problems,
    analyses_checked: keys.length,
};
return [msg, problems.length ? msg : null];

// No require('fs') — same fix as the other two flows, see their
// equivalent nodes for the full explanation (Function nodes are
// sandboxed and have never exposed require()).
let secrets;
try {
    secrets = JSON.parse(msg.payload);
} catch (e) {
    node.error('Could not parse secrets file: ' + e.message, msg);
    return null;
}
msg.secrets = secrets;
msg.job_started_at = new Date().toISOString();
const nowNs = Date.now() * 1000000;
msg.url = secrets.influxdb_url + '/api/v2/write?org=' + secrets.influxdb_org + '&bucket=' + secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = 'sync_job_runs,job_name=bodycomp_import,status=started value=1 ' + nowNs;
return msg;

// `ls` with no matches writes to stderr and exits non-zero — stdout
// (this node's output 1, wired here) is simply empty in that case,
// which is the normal/expected "nothing new to import" outcome, not
// a failure.
const files = (msg.payload || '').split('\n').map(s => s.trim()).filter(Boolean);
if (!files.length) {
    return [null, msg];
}
msg.files = files;
msg.file_index = 0;
msg.all_rows = [];
return [msg, null];

if (msg.file_index >= msg.files.length) {
    // All files read into msg.all_rows — move on to the merge rules.
    return [null, msg];
}
