// discipline as godaddy/sql/upgrade_from_3.0.0.sql, just run inline
// rather than as a separate manual step (Ward, Aug 2026 — "a node red
// task that initializes it, and keeps it up to date"). Identical in
// every flow that writes status — duplicated on purpose, matching this
// project's existing preference for self-contained nodes over a shared-
// context module pattern.
msg.topic = "CREATE TABLE IF NOT EXISTS job_status (" +
    "job_name TEXT PRIMARY KEY, last_success TEXT, last_attempt TEXT, " +
    "last_attempt_ok INTEGER, last_error TEXT, checkpoint TEXT, updated_at TEXT)";
return msg;

// Builds the UPSERT from msg.sqlite_job (set by job_success/job_failed
// above). 'success' mode updates last_success and clears last_error;
// 'failure' mode updates last_error and deliberately leaves last_success
// untouched (a failure shouldn't erase the last known-good run). checkpoint
// is job-specific optional state (only oura_sync uses it, for its self-heal
// fetch window) — only touched when the caller actually supplies one.
function esc(s) { return "'" + String(s).replace(/'/g, "''") + "'"; }
function sqlVal(v) { return (v === null || v === undefined) ? 'NULL' : (typeof v === 'number' ? v : esc(v)); }
const j = msg.sqlite_job;
const now = new Date().toISOString();
const cols = ['job_name', 'last_success', 'last_attempt', 'last_attempt_ok', 'last_error', 'checkpoint', 'updated_at'];
const vals = [j.job_name, j.last_success ?? null, j.last_attempt, j.last_attempt_ok, j.last_error ?? null, j.checkpoint ?? null, now];
const setClauses = ['last_attempt=excluded.last_attempt', 'last_attempt_ok=excluded.last_attempt_ok', 'updated_at=excluded.updated_at'];
if (j.mode === 'success') {
    setClauses.push('last_success=excluded.last_success', 'last_error=NULL');
    if (j.checkpoint !== undefined && j.checkpoint !== null) setClauses.push('checkpoint=excluded.checkpoint');
} else {
    setClauses.push('last_error=excluded.last_error');
}
msg.topic = 'INSERT INTO job_status (' + cols.join(', ') + ') VALUES (' + vals.map(sqlVal).join(', ') + ') ' +
    'ON CONFLICT(job_name) DO UPDATE SET ' + setClauses.join(', ');
return msg;

// Ground-truth checks, not a best-guess pass-through — each one either
// passes or produces a specific, actionable failure message, same
// philosophy as body_comp_xlsx_test.json's approach to a new node.
const doc = msg.payload;
const problems = [];

if (typeof doc !== 'object' || doc === null) {
    problems.push('Top-level result is not an object — typeof=' + typeof doc + '. The yaml node may not be converting to a JS object the way assumed.');
} else {
    if (!Array.isArray(doc.encounters)) {
        problems.push('doc.encounters is not an array — typeof=' + typeof doc.encounters);
    } else {
        if (doc.encounters.length !== 2) {
            problems.push('Expected 2 encounters, got ' + doc.encounters.length);
        }
        const e1 = doc.encounters[0] || {};
        const expectedFields = ['id', 'date', 'date_precision', 'title', 'category', 'encounter_type', 'procedure', 'reason', 'outcome', 'evidence', 'evidence_note', 'related_medications', 'notes'];
        expectedFields.forEach(f => {
            if (!(f in e1)) problems.push('First encounter missing expected field: ' + f);
        });
        if (e1.id !== 'test-encounter-1') problems.push('First encounter id mismatch: got ' + JSON.stringify(e1.id));
        if (!(e1.date instanceof Date) && typeof e1.date !== 'string') {
            problems.push('First encounter date is neither a Date nor a string — typeof=' + typeof e1.date + ' — the live flow\'s n_mhi_prep_push does (e.date || \'\') + \' 00:00:00\', confirm this still produces a sane occurred_at value either way.');
        }
        if (!Array.isArray(e1.related_medications) || e1.related_medications.length !== 2) {
            problems.push('related_medications did not parse as a 2-item array — got ' + JSON.stringify(e1.related_medications));
        }
        const e2 = doc.encounters[1] || {};
        if (e2.procedure !== undefined) problems.push('Sparse second encounter unexpectedly has a procedure field — optional-field omission may not be working as assumed');
    }
    if (!doc.symptom_context || !Array.isArray(doc.symptom_context.items)) {
        problems.push('doc.symptom_context.items did not parse as expected (used only to confirm this section parses at all — the live flow never reads it, PLAN.md §19)');
    }
}

msg.payload = {
    result: problems.length ? 'PROBLEMS FOUND' : 'ALL CHECKS PASSED',
    problems: problems,
    parsed_encounters_count: (doc && Array.isArray(doc.encounters)) ? doc.encounters.length : null,
    parsed_first_encounter: (doc && doc.encounters) ? doc.encounters[0] : null,
    raw_parsed_doc: doc
};
return [msg, problems.length ? msg : null];

try {
