msg.readiness_response = msg.payload;
const startDt = msg.oura_query.start_date + 'T00:00:00';
const endDt = msg.oura_query.end_date + 'T23:59:59';
msg.url = 'https://api.ouraring.com/v2/usercollection/heartrate?' +
