if (msg.payload) node.warn('mkdir stderr (backup dir may not exist): ' + msg.payload);
return null;

const secrets = flow.get('wde_secrets');
const nowNs = Date.now() * 1000000;
msg.url = secrets.influxdb_url + '/api/v2/write?org=' + secrets.influxdb_org + '&bucket=' + secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = 'sync_job_runs,job_name=wherewhen_export,status=started value=1 ' + nowNs;
return msg;

// First InfluxDB QUERY this project's flows have ever made (every other
// flow only ever writes). Content-Type application/vnd.flux + raw Flux
// text body is the documented InfluxDB v2 request shape for this — the
// response is CSV by default, no separate 'give me CSV' step needed.
