const text = msg.payload || '';
const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
const headerLine = lines.find(l => !l.startsWith('#'));
let count = null;
if (headerLine) {
    const cols = headerLine.split(',');
    const valueIdx = cols.indexOf('_value');
    const dataLine = lines[lines.indexOf(headerLine) + 1];
    if (dataLine && valueIdx !== -1) count = parseInt(dataLine.split(',')[valueIdx], 10);
}
return { payload: { measurement: msg.measurement_name, post_restore_count: (Number.isFinite(count) ? count : null) } };

// BALLPARK sanity check, per this tab's own info note — manifest
// row_count includes CSV header/annotation lines from the export side,
// so exact equality against post-restore point counts isn't expected.
