const results = Array.isArray(msg.payload) ? msg.payload : [];
const manifestByName = {};
(manifest.measurements || []).forEach(m => { manifestByName[m] = true; });

const warnings = [];
results.forEach(r => {
    if (r.post_restore_count === null) {
        warnings.push(r.measurement + ': could not read a post-restore count (verify query itself may need checking).');
